#include "../src/cloud_sprite.hpp"
#include <chrono>
#include <iostream>
int main(){const int w=1280,h=720,sw=640,sh=280;weather_graphics::CloudMask mask(256,128,0);weather_graphics::CloudSprite cached;cached.prepare(mask,sw,sh,1,0,0x203044,0x8396ab,70);std::vector<uint32_t> image(w*h,0x182c40);volatile uint64_t checksum=0;double duration[2];for(int mode=0;mode<2;++mode){auto start=std::chrono::steady_clock::now();for(int frame=0;frame<30;++frame){std::fill(image.begin(),image.end(),0x182c40);for(int i=0;i<5;++i){int left=i*190-150+frame,top=i*75-40;if(mode)cached.raster.composite(image.data(),w,h,left,top);else for(int y=std::max(0,top);y<std::min(h,top+sh);++y)for(int x=std::max(0,left);x<std::min(w,left+sw);++x){auto s=mask.at((x-left)*255*256/(sw-1),(y-top)*127*256/(sh-1));uint32_t rgb=0;for(unsigned shift:{0u,8u,16u}){int a=(0x203044>>shift)&255,b=(0x8396ab>>shift)&255;rgb|=(unsigned)(a+(b-a)*int(s.light)/255)<<shift;}image[y*w+x]=rendering::over(image[y*w+x],rendering::premultiply(rgb,s.alpha*70/100));}}checksum+=image[(frame*2701)%(w*h)];}duration[mode]=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()/30;}std::cout<<"Portable cloud-stage benchmark (1280x720, five 640x280 clouds, 30 frames):\nPer-frame resampling: "<<duration[0]<<" ms/frame\nCached sprites: "<<duration[1]<<" ms/frame\nRatio: "<<duration[0]/duration[1]<<"x | One sprite allocated bytes: "<<cached.raster.bytes()<<"\nChecksum: "<<checksum<<"\nLinux build-host result only; excludes Windows/GDI/presentation/foreground and is not a Windows CPU measurement.\n";}
